window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2c78e7771e14cd0e"]={"versions": [{"id": "FIG-2c78e7771e14cd0e", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology SPEM/UML-Profil) für die Software-Integration der AUTOSAR Adaptive Platform. Das Diagramm modelliert die Integration von Softwarekomponenten, Schnittstellenheadern und Plattform-Objektcode zu einer ausführbaren Applikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Integrate Software</code>: Hauptaktivität zur Zusammenführung der Komponenten und Erzeugung der Binärdatei.\n</li></ul>\n<p class=\"fig-p\">Teilaktivitäten (über Kompositions-/Nesting-Kanten <code>«nesting»</code> zugeordnet):</p>\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build Executable Application</code>\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (über Beziehungsstereotyp <code>«input»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Header Files for Service Interfaces</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Platform Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Main Function</code> (Kardinalität <code>1</code>)\n</li><li><code>Build Chain Configuration</code> (Kardinalität <code>1</code>)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt (über Beziehungsstereotyp <code>«output»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Executable Application</code> (Kardinalität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der Eingangsartefakte: Service-Interface-Beschreibungen, C++ Header-Dateien für Service-Schnittstellen, kompilierter Objektcode der Softwarekomponenten und der Plattform sowie die Quellcodedatei mit der <code>Main Function</code> und die <code>Build Chain Configuration</code>.\n</li><li>Schachtelung und Ausführung der Integrationsschritte:\n<ul class=\"fig-list\"><li>Konfiguration der platformspezifischen Serialisierungsmechanismen (<code>Configure Serialization for Adaptive Platform</code>).\n</li><li>Automatische Generierung des Serialisierungscodes für die Adaptive Platform (<code>Generate Serialization Code for Adaptive Platform</code>).\n</li><li>Kompilierung und Link-Vorgang zur fertigen Applikation (<code>Build Executable Application</code>).\n</li></ul>\n</li><li>Ausgabe der fertigen Binärdatei <code>Executable Application</code> (Kardinalität 1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Integrationsprozess erfordert zwingend genau eine <code>Main Function</code> und eine <code>Build Chain Configuration</code> (Kardinalität 1). Software Component Object Code, Platform Object Code sowie Service Interface Descriptions und Header Files können in beliebiger Anzahl (Kardinalität <code>0..*</code>) eingebracht werden. Ergebnis des Prozesses ist deterministisch genau eine lauffähige <code>Executable Application</code>. Die Serialisierungskonfiguration und -codegenerierung stellen bindende methodische Zwischenschritte innerhalb des Build-Vorgangs für die Adaptive Platform dar.</p>"}, {"id": "FIG-f808822290690ed0", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology SPEM/UML-Profil) für die Software-Integration der AUTOSAR Adaptive Platform mit Zuweisung einer Organisationsrolle (Tier 1 / Software Integrator) und Quellcode-Pfad.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Rolle:</p>\n<ul class=\"fig-list\"><li><code>Tier 1</code> agiert über <code>«performs»</code> als <code>+Software Integrator</code> für die Aktivität <code>Integrate Software</code>.\n</li></ul>\n<p class=\"fig-p\">Zentrale Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Integrate Software</code>: Hauptaktivität zur Software-Integration.\n</li></ul>\n<p class=\"fig-p\">Teilaktivitäten (über <code>«nesting»</code> zugeordnet):</p>\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build Executable Application</code>\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (über <code>«input»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Platform Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Service Interface Description</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Header Files for Service Interfaces</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Source Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Main Function</code> (Kardinalität <code>1</code>)\n</li><li><code>Build Chain Configuration</code> (Kardinalität <code>1</code>)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt (über <code>«output»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Executable Application</code> (Kardinalität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Einbindung der organisatorischen Rolle <code>+Software Integrator</code> (<code>Tier 1</code>), die den Gesamtprozess <code>Integrate Software</code> steuert und ausführt.\n</li><li>Zuführung der Eingangsartefakte: Objektcode (Plattform und SWC), Quellcode (<code>Software Component Source Code</code>), Service-Interface-Beschreibungen, Schnittstellen-Header, <code>Main Function</code> sowie <code>Build Chain Configuration</code>.\n</li><li>Ausführung der geschachtelten Teilschritte:\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build Executable Application</code>\n</li></ul>\n</li><li>Erzeugung und Auslieferung der <code>Executable Application</code> (Kardinalität 1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik erlaubt neben vorab kompiliertem Objektcode (<code>Software Component Object Code</code>) explizit auch die direkte Integration von C++ Quellcode (<code>Software Component Source Code</code>, <code>0..*</code>), wodurch der Build-Prozess im Rahmen der Integration auch das Übersetzen von Komponenten-Quellcode umfasst. Die manuelle oder werkzeuggestützte Implementierung von Service-Proxies und Service-Skeletons (<code>Implement Service Proxies and Skeletons</code>) ist als eigenständiger methodischer Teilschritt normiert und der Verantwortung des <code>Software Integrator</code> (Rolle <code>Tier 1</code>) unterstellt.</p>"}, {"id": "FIG-da9476be5cf5c0b4", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology SPEM/UML-Profil) für die Software-Integration der AUTOSAR Adaptive Platform mit Zuweisung einer Organisationsrolle (Tier 1 / Software Integrator) und Quellcode-Pfad.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Rolle:</p>\n<ul class=\"fig-list\"><li><code>Tier 1</code> agiert über <code>«performs»</code> als <code>+Software Integrator</code> für die Aktivität <code>Integrate Software</code>.\n</li></ul>\n<p class=\"fig-p\">Zentrale Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Integrate Software</code>: Hauptaktivität zur Software-Integration.\n</li></ul>\n<p class=\"fig-p\">Teilaktivitäten (über <code>«nesting»</code> zugeordnet):</p>\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build Executable Application</code>\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (über <code>«input»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Platform Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Service Interface Description</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Header Files for Service Interfaces</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Source Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Main Function</code> (Kardinalität <code>1</code>)\n</li><li><code>Build Chain Configuration</code> (Kardinalität <code>1</code>)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt (über <code>«output»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Executable Application</code> (Kardinalität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Einbindung der organisatorischen Rolle <code>+Software Integrator</code> (<code>Tier 1</code>), die den Gesamtprozess <code>Integrate Software</code> steuert und ausführt.\n</li><li>Zuführung der Eingangsartefakte: Objektcode (Plattform und SWC), Quellcode (<code>Software Component Source Code</code>), Service-Interface-Beschreibungen, Schnittstellen-Header, <code>Main Function</code> sowie <code>Build Chain Configuration</code>.\n</li><li>Ausführung der geschachtelten Teilschritte:\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build Executable Application</code>\n</li></ul>\n</li><li>Erzeugung und Auslieferung der <code>Executable Application</code> (Kardinalität 1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik erlaubt neben vorab kompiliertem Objektcode (<code>Software Component Object Code</code>) explizit auch die direkte Integration von C++ Quellcode (<code>Software Component Source Code</code>, <code>0..*</code>), wodurch der Build-Prozess im Rahmen der Integration auch das Übersetzen von Komponenten-Quellcode umfasst. Die manuelle oder werkzeuggestützte Implementierung von Service-Proxies und Service-Skeletons (<code>Implement Service Proxies and Skeletons</code>) ist als eigenständiger methodischer Teilschritt normiert und der Verantwortung des <code>Software Integrator</code> (Rolle <code>Tier 1</code>) unterstellt.</p>"}, {"id": "FIG-d65eee9668a897e9", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology SPEM/UML-Profil) für die Software-Integration der AUTOSAR Adaptive Platform zur Erzeugung eines (Adaptive) Executable.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Rolle:</p>\n<ul class=\"fig-list\"><li><code>Tier 1</code> agiert über <code>«performs»</code> als <code>+Software Integrator</code> für die Aktivität <code>Integrate Software</code>.\n</li></ul>\n<p class=\"fig-p\">Zentrale Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Integrate Software</code>: Hauptaktivität zur Software-Integration.\n</li></ul>\n<p class=\"fig-p\">Teilaktivitäten (über <code>«nesting»</code> zugeordnet):</p>\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build (Adaptive) Executable</code>\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (über <code>«input»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Platform Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Service Interface Description</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Header Files for Service Interfaces</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Source Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Main Function</code> (Kardinalität <code>1</code>)\n</li><li><code>Build Chain Configuration</code> (Kardinalität <code>1</code>)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt (über <code>«output»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>(Adaptive) Executable</code> (Kardinalität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausführung der Hauptaktivität <code>Integrate Software</code> durch den <code>+Software Integrator</code> (<code>Tier 1</code>).\n</li><li>Entgegennahme der Eingangsartefakte (Plattform-Objektcode, Service-Interface-Beschreibungen, Service-Interface-Header, SWC-Objektcode, SWC-Quellcode, Main Function, Build-Chain-Konfiguration).\n</li><li>Durchführung der geschachtelten Teilschritte:\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build (Adaptive) Executable</code>\n</li></ul>\n</li><li>Ausgabe des gebauten <code>(Adaptive) Executable</code> (Kardinalität 1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Erzeugnis der Integrationsaktivität und des Build-Schritts wird formell als <code>(Adaptive) Executable</code> spezifiziert. Der Build-Schritt <code>Build (Adaptive) Executable</code> fasst die Verlinkung und Erstellung der plattformkonformen ausführbaren Datei der Adaptive Platform zusammen, während alle Eingangsabhängigkeiten und Kardinalitäten unverändert verbindlich bleiben.</p>"}, {"id": "FIG-9d9e63ed8f1ea62d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology SPEM/UML-Profil) für die Software-Integration der AUTOSAR Adaptive Platform zur Erzeugung eines (Adaptive) Executable.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Rolle:</p>\n<ul class=\"fig-list\"><li><code>Tier 1</code> agiert über <code>«performs»</code> als <code>+Software Integrator</code> für die Aktivität <code>Integrate Software</code>.\n</li></ul>\n<p class=\"fig-p\">Zentrale Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Integrate Software</code>: Hauptaktivität zur Software-Integration.\n</li></ul>\n<p class=\"fig-p\">Teilaktivitäten (über <code>«nesting»</code> zugeordnet):</p>\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build (Adaptive) Executable</code>\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (über <code>«input»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>Platform Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Service Interface Description</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Header Files for Service Interfaces</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Object Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Software Component Source Code</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Main Function</code> (Kardinalität <code>1</code>)\n</li><li><code>Build Chain Configuration</code> (Kardinalität <code>1</code>)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt (über <code>«output»</code> verbunden):</p>\n<ul class=\"fig-list\"><li><code>(Adaptive) Executable</code> (Kardinalität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausführung der Hauptaktivität <code>Integrate Software</code> durch den <code>+Software Integrator</code> (<code>Tier 1</code>).\n</li><li>Entgegennahme der Eingangsartefakte (Plattform-Objektcode, Service-Interface-Beschreibungen, Service-Interface-Header, SWC-Objektcode, SWC-Quellcode, Main Function, Build-Chain-Konfiguration).\n</li><li>Durchführung der geschachtelten Teilschritte:\n<ul class=\"fig-list\"><li><code>Configure Serialization for Adaptive Platform</code>\n</li><li><code>Implement Service Proxies and Skeletons</code>\n</li><li><code>Generate Serialization Code for Adaptive Platform</code>\n</li><li><code>Build (Adaptive) Executable</code>\n</li></ul>\n</li><li>Ausgabe des gebauten <code>(Adaptive) Executable</code> (Kardinalität 1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Erzeugnis der Integrationsaktivität und des Build-Schritts wird formell als <code>(Adaptive) Executable</code> spezifiziert. Der Build-Schritt <code>Build (Adaptive) Executable</code> fasst die Verlinkung und Erstellung der plattformkonformen ausführbaren Datei der Adaptive Platform zusammen, während alle Eingangsabhängigkeiten und Kardinalitäten unverändert verbindlich bleiben.</p>"}], "trans": [{"from": "FIG-2c78e7771e14cd0e", "to": "FIG-f808822290690ed0", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Rolle ergänzt: <code>Tier 1</code> führt über Assoziation <code>«performs»</code> die Rolle <code>+Software Integrator</code> für die Aktivität <code>Integrate Software</code> aus.\n</li><li>Artefakt ergänzt: <code>Software Component Source Code</code> (Kardinalität <code>0..*</code>) als Eingabe (<code>«input»</code>) für <code>Integrate Software</code>.\n</li><li>Teilaktivität ergänzt: <code>Implement Service Proxies and Skeletons</code> als geschachtelter Teilschritt (<code>«nesting»</code>) unter <code>Integrate Software</code>.\n</li><li>Layout umstrukturiert: Die Artefakte <code>Platform Object Code</code> und <code>Service Interface Description</code> wurden von der oberen Position in die linke vertikale Eingangsspalte verschoben; Verbindungsführung neu ausgerichtet.\n</li></ul>"}, {"from": "FIG-f808822290690ed0", "to": "FIG-da9476be5cf5c0b4", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Layout angepasst: Pfeilverbindungen von <code>Tier 1</code> (<code>«performs»</code>) und den Teilaktivitäten (<code>«nesting»</code>) zur zentralen Aktivität <code>Integrate Software</code> wurden mit leicht modifizierten Anschlusspunkten und Winkeln neu geroutet.\n</li><li>Textumbruch: Der Text <code>Build Chain Configuration</code> ist am unteren linken Rand leicht verschoben bzw. beschnitten gerendert.\n</li></ul>"}, {"from": "FIG-da9476be5cf5c0b4", "to": "FIG-d65eee9668a897e9", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Artefakt umbenannt: Ausgangsartefakt <code>Executable Application</code> umbenannt in <code>(Adaptive) Executable</code>.\n</li><li>Teilaktivität umbenannt: Teilaktivität <code>Build Executable Application</code> umbenannt in <code>Build (Adaptive) Executable</code>.\n</li></ul>"}, {"from": "FIG-d65eee9668a897e9", "to": "FIG-9d9e63ed8f1ea62d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
